class Solution {
public:
    ListNode* deleteMiddle(ListNode* head) {
        if (!head || !head->next) return nullptr;
        ListNode* slow=head; ListNode* fast=head->next->next;
        while (fast && fast->next) {
            slow=slow->next; fast=fast->next->next;
        }
        ListNode* dead=slow->next;
        slow->next=dead->next;
        delete dead;
        return head;
    }
};
